// Web Programming — real lessons (enrichment beyond CAPS; builds on the HTML in CAPS Information Technology Grade 10).
LESSON_DB.webprog = LESSON_DB.webprog || {};

// ─── Module 0: HTML Foundations ─────────────────────────────────────────────
LESSON_DB.webprog.m0 = {
  0: {emoji:"🌐", subtitle:"Enrichment · How the web works",
    illusText:"Browser → DNS → server → HTML, CSS and JavaScript back to your screen.",
    hook:{title:"What happens when you open Takealot?", body:"You type an address, press Enter, and a second later a whole shop appears. In that second your phone asked a <strong>DNS server</strong> where the site lives, sent a <strong>request</strong> to a computer that might be in Cape Town or Ireland, and got back files your <strong>browser</strong> turned into a page. Every web developer starts by understanding that journey."},
    intro:"The <strong>internet</strong> is the global network of connected computers; the <strong>web</strong> is the collection of pages and apps that run on it. A <strong>URL</strong> (e.g. https://www.example.co.za/shop) has a protocol (https), a domain (example.co.za) and a path (/shop). <strong>DNS</strong> (Domain Name System) translates a domain into an <strong>IP address</strong>. The browser (the <strong>client</strong>) sends an <strong>HTTP request</strong> to the <strong>server</strong>, which sends back a <strong>response</strong> with a <strong>status code</strong> (200 OK, 404 Not Found, 500 Server Error) and files. Web pages are built from three languages: <strong>HTML</strong> (structure and content), <strong>CSS</strong> (presentation) and <strong>JavaScript</strong> (behaviour). <strong>HTTPS</strong> encrypts the connection — look for the padlock before entering passwords.",
    concepts:[
      {t:"green", title:"🔎 DNS", body:"Turns a name like example.co.za into an IP address."},
      {t:"teal", title:"🔁 Request and response", body:"The browser asks; the server answers with a status code and files."},
      {t:"gold", title:"🧱 HTML · CSS · JS", body:"Structure, style and behaviour."},
    ],
    examples:[
      {title:"Status code", body:"You click a broken link and see “Page not found”.", answer:"The server returned <strong>404 Not Found</strong>."},
      {title:"URL parts", body:"https://www.sars.gov.za/tax-rates", answer:"Protocol <strong>https</strong>, domain <strong>www.sars.gov.za</strong>, path <strong>/tax-rates</strong>."},
      {title:"Roles", body:"Which language makes a button do something when clicked?", answer:"<strong>JavaScript</strong>."},
    ],
    mistakes:["Saying the internet and the web are the same thing.","Thinking HTTP and HTTPS are equally safe.","Believing a website lives “in the browser” — it lives on a server."],
    callout:{title:"Try it", body:"Press F12 (or long-press → Inspect on desktop browsers) and open the Network tab to watch every request a page makes."},
    activity:"Open any website, open the browser's developer tools, reload the page and count how many files were loaded. Which file types do you see?",
    activityAnswer:"Answers vary — typically dozens of files: one HTML document, several CSS and JavaScript files, images (png, jpg, webp, svg) and fonts.",
    examTip:"Remember the order: DNS lookup → request → response → the browser renders HTML, then applies CSS, then runs JavaScript.",
    keyterms:[{w:"DNS",d:"System that turns domain names into IP addresses"},{w:"Client",d:"The device or browser that requests pages"},{w:"Status code",d:"Number showing the result of a request (200, 404, 500)"}],
    quiz:[
      {q:"What does DNS do?",opts:["Styles pages","Turns domain names into IP addresses","Encrypts passwords","Stores images"],a:1,et:"The internet's phone book."},
      {q:"Status code 404 means:",opts:["OK","Server error","Not found","Redirect"],a:2,et:"The resource doesn't exist."},
      {q:"Which language adds behaviour?",opts:["HTML","CSS","JavaScript","SQL"],a:2,et:"Clicks, animations, data."},
    ],
    conclusion:"The browser asks, the server answers, and HTML, CSS and JavaScript work together to build what you see."},

  1: {emoji:"🧱", subtitle:"Enrichment · HTML structure and tags",
    illusText:"Every page: &lt;!DOCTYPE html&gt;, &lt;html&gt;, &lt;head&gt;, &lt;body&gt;.",
    hook:{title:"Your first web page in 10 lines", body:"Every website — from Wikipedia to your favourite online store — starts with the same skeleton of <strong>HTML</strong> tags. Learn ten lines and you can build a page that runs on any phone in the world, for free."},
    intro:"HTML uses <strong>elements</strong> made of tags: an opening tag <code>&lt;p&gt;</code>, content, and a closing tag <code>&lt;/p&gt;</code>. Some elements are empty (<code>&lt;br&gt;</code>, <code>&lt;img&gt;</code>). Tags can have <strong>attributes</strong>, e.g. <code>&lt;html lang=\"en\"&gt;</code>. The basic skeleton: <code>&lt;!DOCTYPE html&gt;</code>, then <code>&lt;html&gt;</code> containing a <code>&lt;head&gt;</code> (information about the page: <code>&lt;meta charset=\"utf-8\"&gt;</code>, the viewport meta tag for phones, and <code>&lt;title&gt;</code>) and a <code>&lt;body&gt;</code> (what users see). Headings go from <code>&lt;h1&gt;</code> (most important, one per page) to <code>&lt;h6&gt;</code>. Paragraphs use <code>&lt;p&gt;</code>. Elements <strong>nest</strong> inside each other — close them in reverse order. Comments: <code>&lt;!-- note --&gt;</code>.",
    concepts:[
      {t:"green", title:"🏷️ Elements", body:"Opening tag, content, closing tag."},
      {t:"teal", title:"🧠 Head vs body", body:"Head = information about the page; body = what users see."},
      {t:"gold", title:"🪆 Nesting", body:"Close tags in the reverse order you opened them."},
    ],
    examples:[
      {title:"Fix it", body:"<code>&lt;p&gt;Hello &lt;b&gt;Mzansi&lt;/p&gt;&lt;/b&gt;</code>", answer:"Close in reverse order: <code>&lt;p&gt;Hello &lt;b&gt;Mzansi&lt;/b&gt;&lt;/p&gt;</code>."},
      {title:"Where does it go?", body:"The text shown on the browser tab.", answer:"In <code>&lt;title&gt;</code>, inside the <strong>head</strong>."},
      {title:"Headings", body:"How many <code>&lt;h1&gt;</code> headings should a page have?", answer:"Usually <strong>one</strong> — the main title of the page."},
    ],
    mistakes:["Forgetting closing tags.","Putting visible content in the head.","Leaving out the viewport meta tag, so the page looks tiny on phones."],
    callout:{title:"Phone-ready", body:"Always include <code>&lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"&gt;</code>."},
    activity:"Create a file called index.html with the full skeleton, an h1 with your name and two paragraphs about your favourite place in South Africa. Open it in a browser.",
    activityAnswer:"The page should show your heading and paragraphs. Check: DOCTYPE first, one html element, head with charset, viewport and title, and all content inside body.",
    examTip:"Check nesting by indenting your code — every child sits one level in.",
    keyterms:[{w:"Element",d:"An opening tag, content and closing tag"},{w:"Attribute",d:"Extra information inside an opening tag"},{w:"Nesting",d:"Placing elements inside other elements"}],
    quiz:[
      {q:"Visible content goes in the:",opts:["head","body","title","meta"],a:1,et:"The head holds information about the page."},
      {q:"Which is an empty element?",opts:["&lt;p&gt;","&lt;h1&gt;","&lt;br&gt;","&lt;body&gt;"],a:2,et:"No closing tag needed."},
      {q:"The tab text comes from:",opts:["&lt;h1&gt;","&lt;title&gt;","&lt;header&gt;","&lt;p&gt;"],a:1,et:"Inside the head."},
    ],
    conclusion:"A doctype, an html element, a head and a body — with properly nested tags — is the skeleton of every web page."},

  2: {emoji:"🔗", subtitle:"Enrichment · Text, links and images",
    illusText:"&lt;a href&gt; links pages together; &lt;img src alt&gt; adds pictures.",
    hook:{title:"The web is a web because of links", body:"Wikipedia articles link to other articles, which link to more. Without the humble <code>&lt;a&gt;</code> tag there'd be no web at all — just separate documents. Add images with good descriptions and your page becomes useful to everyone, including blind users with screen readers."},
    intro:"<strong>Links</strong>: <code>&lt;a href=\"https://www.gov.za\"&gt;SA Government&lt;/a&gt;</code>. Absolute URLs include the full address; <strong>relative</strong> URLs point to files in your site (<code>href=\"about.html\"</code>). Open in a new tab with <code>target=\"_blank\"</code> (add <code>rel=\"noopener\"</code>). Link to part of a page with an id: <code>href=\"#contact\"</code>. Email links: <code>href=\"mailto:info@example.co.za\"</code>. <strong>Images</strong>: <code>&lt;img src=\"protea.jpg\" alt=\"A pink king protea\" width=\"400\"&gt;</code>. The <strong>alt</strong> text describes the image for screen readers and shows if the image fails to load. Formats: JPG (photos), PNG (sharp graphics, transparency), SVG (logos and icons that scale), WebP (small and modern). <strong>Text formatting</strong>: <code>&lt;strong&gt;</code> (important), <code>&lt;em&gt;</code> (emphasis), <code>&lt;br&gt;</code> (line break), <code>&lt;blockquote&gt;</code> (quotes).",
    concepts:[
      {t:"green", title:"🔗 href", body:"Where the link goes — absolute or relative."},
      {t:"teal", title:"🖼️ alt text", body:"Describes images for everyone who can't see them."},
      {t:"gold", title:"📦 Formats", body:"JPG photos, PNG graphics, SVG icons, WebP small files."},
    ],
    examples:[
      {title:"Relative link", body:"Link from index.html to contact.html in the same folder.", answer:"<code>&lt;a href=\"contact.html\"&gt;Contact us&lt;/a&gt;</code>"},
      {title:"Good alt text", body:"A photo of Table Mountain with a cloud on top.", answer:"<code>alt=\"Table Mountain covered by its tablecloth of cloud\"</code> — describe what matters, not “image”."},
      {title:"Format", body:"Which format for a logo that must stay sharp at any size?", answer:"<strong>SVG</strong>."},
    ],
    mistakes:["Writing alt=\"image\" or leaving alt out.","Using huge photos that make pages slow on mobile data.","Linking text like “click here” instead of describing where the link goes."],
    callout:{title:"Save data", body:"Resize photos before uploading — a 4 MB phone photo can usually become 150 KB without looking worse."},
    activity:"Build a “My Top 3 SA Places” page with three images (with alt text) and a link to more information for each place.",
    activityAnswer:"Check that each image has a meaningful alt, links have descriptive text, external links use target=\"_blank\" with rel=\"noopener\", and images are a sensible size.",
    examTip:"Every img needs src and alt — examiners and accessibility checkers look for both.",
    keyterms:[{w:"href",d:"The destination of a link"},{w:"alt",d:"Text alternative for an image"},{w:"Relative URL",d:"A path to a file within the same site"}],
    quiz:[
      {q:"Which attribute holds a link's destination?",opts:["src","href","alt","rel"],a:1,et:"Hypertext reference."},
      {q:"alt text is mainly for:",opts:["Search ads","Screen readers and failed images","Colours","Speed"],a:1,et:"Accessibility first."},
      {q:"Best format for a photo:",opts:["SVG","JPG","TXT","GIF"],a:1,et:"Or WebP for smaller files."},
    ],
    conclusion:"Links connect the web and images bring it to life — always with meaningful link text and alt text."},

  3: {emoji:"📋", subtitle:"Enrichment · Lists, tables and forms",
    illusText:"&lt;ul&gt; &lt;ol&gt; for lists · &lt;table&gt; for data · &lt;form&gt; to collect input.",
    hook:{title:"The bursary application form", body:"Every online application — NSFAS, a bursary, a job — is an HTML <strong>form</strong>. Behind the scenes the page also uses <strong>lists</strong> for requirements and <strong>tables</strong> for deadlines. Learn these three and you can build the pages that change people's futures."},
    intro:"<strong>Lists</strong>: unordered <code>&lt;ul&gt;</code> (bullets) and ordered <code>&lt;ol&gt;</code> (numbers), each item in <code>&lt;li&gt;</code>. <strong>Tables</strong> are for data, not layout: <code>&lt;table&gt;</code>, rows <code>&lt;tr&gt;</code>, header cells <code>&lt;th&gt;</code>, data cells <code>&lt;td&gt;</code>; add a <code>&lt;caption&gt;</code>. <strong>Forms</strong>: <code>&lt;form action=\"...\" method=\"post\"&gt;</code> containing <code>&lt;label&gt;</code> and <code>&lt;input&gt;</code> pairs. Input types: text, email, password, number, date, tel, checkbox, radio, file. Other controls: <code>&lt;select&gt;</code> with <code>&lt;option&gt;</code>, <code>&lt;textarea&gt;</code>, <code>&lt;button type=\"submit\"&gt;</code>. Connect a label to an input with <code>for</code> and <code>id</code>. Built-in validation: <code>required</code>, <code>min</code>, <code>max</code>, <code>pattern</code>. The <code>name</code> attribute is what the server receives.",
    concepts:[
      {t:"green", title:"📝 Lists", body:"ul for bullets, ol for steps, li for items."},
      {t:"teal", title:"📊 Tables", body:"For data only — th for headings, td for cells."},
      {t:"gold", title:"🧾 Forms", body:"Labels, inputs with types, names and validation."},
    ],
    examples:[
      {title:"List choice", body:"Steps to apply for a bursary.", answer:"An <strong>ordered list</strong> <code>&lt;ol&gt;</code> — the order matters."},
      {title:"Input type", body:"Collect a learner's email address.", answer:"<code>&lt;input type=\"email\" id=\"email\" name=\"email\" required&gt;</code> — the browser checks the format."},
      {title:"Label", body:"Why use <code>&lt;label for=\"email\"&gt;</code>?", answer:"Tapping the label focuses the input, and <strong>screen readers</strong> read the label."},
    ],
    mistakes:["Using tables to lay out a whole page.","Inputs without labels.","Forgetting the name attribute, so data never reaches the server."],
    callout:{title:"Phone keyboards", body:"type=\"tel\" and type=\"email\" show the right keyboard on phones — a small change users love."},
    activity:"Build a registration form for a school soccer tournament: name, grade (select), email, position (radio buttons), and a submit button. Make name and email required.",
    activityAnswer:"Check: every input has a label linked with for/id, name attributes are present, grade uses select/option, positions share the same radio name, and required is on name and email.",
    examTip:"Radio buttons in a group must share the same name — otherwise users can select more than one.",
    keyterms:[{w:"li",d:"A list item"},{w:"th",d:"A table header cell"},{w:"Validation",d:"Checking input before it's submitted"}],
    quiz:[
      {q:"Which list shows numbers?",opts:["ul","ol","dl","li"],a:1,et:"Ordered list."},
      {q:"Which attribute names data sent to the server?",opts:["id","name","class","for"],a:1,et:"name=value pairs."},
      {q:"Tables should be used for:",opts:["Page layout","Tabular data","Images","Navigation"],a:1,et:"Use CSS for layout."},
    ],
    conclusion:"Lists organise, tables present data and forms collect it — always with labels and the right input types."},

  4: {emoji:"🏗️", subtitle:"Enrichment · Semantic HTML5",
    illusText:"&lt;header&gt; &lt;nav&gt; &lt;main&gt; &lt;section&gt; &lt;article&gt; &lt;aside&gt; &lt;footer&gt;.",
    hook:{title:"Div soup", body:"Many beginner pages are built from hundreds of <code>&lt;div&gt;</code> tags — “div soup”. It works, but search engines and screen readers can't tell the menu from the main story. <strong>Semantic</strong> HTML5 tags describe what each part of the page <em>is</em>."},
    intro:"<strong>Semantic elements</strong> describe their meaning: <code>&lt;header&gt;</code> (top of a page or section), <code>&lt;nav&gt;</code> (main navigation links), <code>&lt;main&gt;</code> (the unique main content — one per page), <code>&lt;section&gt;</code> (a themed group with a heading), <code>&lt;article&gt;</code> (self-contained content like a blog post or news story), <code>&lt;aside&gt;</code> (related side content), <code>&lt;footer&gt;</code> (bottom: contact, copyright), <code>&lt;figure&gt;</code> and <code>&lt;figcaption&gt;</code> (an image with a caption). <code>&lt;div&gt;</code> and <code>&lt;span&gt;</code> are <strong>non-semantic</strong> — use them only for styling when no semantic tag fits. Benefits: better accessibility (screen readers can jump to nav or main), better SEO, and code that's easier to read and maintain.",
    concepts:[
      {t:"green", title:"🏷️ Meaning", body:"Tags that describe what content is."},
      {t:"teal", title:"🧭 Landmarks", body:"header, nav, main, footer help screen-reader users navigate."},
      {t:"gold", title:"📦 div last", body:"Use div/span only when nothing semantic fits."},
    ],
    examples:[
      {title:"Choose a tag", body:"A news story that could be shared on its own.", answer:"<code>&lt;article&gt;</code>."},
      {title:"Choose a tag", body:"The site menu with links to Home, Courses, Contact.", answer:"<code>&lt;nav&gt;</code>."},
      {title:"Choose a tag", body:"A photo of a learner with a caption below it.", answer:"<code>&lt;figure&gt;</code> with <code>&lt;figcaption&gt;</code>."},
    ],
    mistakes:["More than one main element per page.","Using section without a heading.","Wrapping everything in div when a semantic tag exists."],
    callout:{title:"Outline test", body:"If you removed all CSS, could someone still tell the menu, main content and footer apart? That's good semantics."},
    activity:"Rewrite this as semantic HTML: a div with a logo and menu, a div with three news stories, a div with a sidebar of links and a div with the copyright.",
    activityAnswer:"header (logo) + nav (menu); main containing three article elements; aside for the sidebar links; footer for the copyright.",
    examTip:"Know the difference between section (a themed part of the page) and article (content that stands alone).",
    keyterms:[{w:"Semantic",d:"Describing meaning, not appearance"},{w:"Landmark",d:"A page region screen readers can jump to"},{w:"SEO",d:"Search engine optimisation"}],
    quiz:[
      {q:"How many main elements per page?",opts:["None","One","Two","Unlimited"],a:1,et:"The unique content."},
      {q:"A blog post should use:",opts:["aside","article","nav","span"],a:1,et:"Self-contained."},
      {q:"Which is non-semantic?",opts:["footer","div","header","nav"],a:1,et:"Says nothing about meaning."},
    ],
    conclusion:"Semantic tags make pages meaningful to browsers, search engines and screen readers — and easier for you to maintain."},

  5: {emoji:"♿", subtitle:"Enrichment · Accessibility and SEO",
    illusText:"Contrast · alt text · keyboard access · headings · meta description.",
    hook:{title:"A website for everyone", body:"Over 7% of South Africans live with a disability. A blind learner using a screen reader, a learner with low vision on a cracked phone, or someone who can't use a mouse should all be able to use your site. Build for <strong>accessibility</strong> and you'll also rank better on Google — the same habits help <strong>SEO</strong>."},
    intro:"<strong>Accessibility (a11y)</strong>: follow the WCAG guidelines. Key habits: meaningful <strong>alt text</strong>; enough <strong>colour contrast</strong> (at least 4.5:1 for normal text); don't use colour alone to show meaning; every input has a <strong>label</strong>; the site works with the <strong>keyboard</strong> (Tab, Enter, visible focus outlines); headings in order (h1 → h2 → h3); descriptive link text; captions for videos; set the page language (<code>lang=\"en\"</code>). <strong>SEO</strong> (search engine optimisation): a clear <code>&lt;title&gt;</code>; a <code>&lt;meta name=\"description\"&gt;</code>; one h1 with the main topic; semantic HTML; fast loading (small images); mobile-friendly design; descriptive URLs (/bursaries-2026, not /page?id=7); and quality content people link to. Test with Lighthouse in Chrome's developer tools.",
    concepts:[
      {t:"green", title:"♿ Accessibility", body:"Alt text, contrast, labels, keyboard access."},
      {t:"teal", title:"🔍 SEO", body:"Title, description, headings, speed, mobile."},
      {t:"gold", title:"🧪 Test", body:"Lighthouse and a screen reader show what to fix."},
    ],
    examples:[
      {title:"Contrast", body:"Light grey text on a white background.", answer:"<strong>Too little contrast</strong> — darken the text so it reaches at least 4.5:1."},
      {title:"Keyboard", body:"A menu only opens on mouse hover.", answer:"Keyboard users can't open it — make it open on <strong>focus/click</strong> too."},
      {title:"SEO", body:"Which tag gives Google the summary under your link?", answer:"<code>&lt;meta name=\"description\" content=\"...\"&gt;</code>."},
    ],
    mistakes:["Removing focus outlines with CSS.","Skipping heading levels just to change text size.","Red/green colour alone to show right and wrong answers."],
    callout:{title:"Quick test", body:"Put your mouse away and try to use your site with only the Tab and Enter keys."},
    activity:"Run a Lighthouse report (Chrome → Inspect → Lighthouse) on a site you use. Note the Accessibility and SEO scores and three suggested fixes.",
    activityAnswer:"Answers vary. Common findings: missing alt text, low contrast, buttons without accessible names, missing meta description, images not properly sized.",
    examTip:"Link each accessibility habit to the user it helps — that's what makes an answer complete.",
    keyterms:[{w:"WCAG",d:"Web Content Accessibility Guidelines"},{w:"Contrast ratio",d:"Brightness difference between text and background"},{w:"Meta description",d:"Summary shown in search results"}],
    quiz:[
      {q:"Minimum contrast for normal text (WCAG AA):",opts:["2:1","3:1","4.5:1","10:1"],a:2,et:"Large text can be 3:1."},
      {q:"Which helps keyboard users most?",opts:["Visible focus outlines","Hover-only menus","Tiny buttons","Autoplay video"],a:0,et:"They show where you are."},
      {q:"Search-result summaries come from:",opts:["alt text","meta description","footer","h6"],a:1,et:"Keep it under about 160 characters."},
    ],
    conclusion:"Accessible, well-structured pages work for everyone — and search engines reward the same good habits."},
};

// ─── Module 1: CSS Styling ──────────────────────────────────────────────────
LESSON_DB.webprog.m1 = {
  0: {emoji:"🎨", subtitle:"Enrichment · CSS selectors and properties",
    illusText:"selector { property: value; } — and the cascade decides who wins.",
    hook:{title:"Same HTML, different outfit", body:"The same HTML can look like a newspaper, a game or a bank app — it all depends on the <strong>CSS</strong>. CSS is like the clothes a page wears: change the stylesheet and the whole site gets a new look without touching the content."},
    intro:"A CSS <strong>rule</strong>: <code>selector { property: value; }</code>, e.g. <code>h1 { color: green; }</code>. Add CSS with an external file (<code>&lt;link rel=\"stylesheet\" href=\"style.css\"&gt;</code> — best), a <code>&lt;style&gt;</code> block, or inline <code>style=\"\"</code> (avoid). <strong>Selectors</strong>: element (<code>p</code>), class (<code>.card</code> — reusable), id (<code>#logo</code> — unique), descendant (<code>nav a</code>), group (<code>h1, h2</code>), pseudo-classes (<code>a:hover</code>, <code>input:focus</code>). <strong>The cascade</strong>: when rules conflict, more <strong>specific</strong> selectors win (id &gt; class &gt; element), and later rules beat earlier ones with the same specificity. Some properties are <strong>inherited</strong> (color, font-family) by children. Use classes for styling most things.",
    concepts:[
      {t:"green", title:"🎯 Selectors", body:"Element, .class, #id, descendant, :hover."},
      {t:"teal", title:"🌊 Cascade", body:"Specificity, then order, decides which rule wins."},
      {t:"gold", title:"📄 External CSS", body:"One stylesheet styles every page."},
    ],
    examples:[
      {title:"Which wins?", body:"<code>p { color: blue; }</code> and <code>.note { color: red; }</code> on <code>&lt;p class=\"note\"&gt;</code>.", answer:"<strong>Red</strong> — a class is more specific than an element."},
      {title:"Selector", body:"Style only links inside the nav.", answer:"<code>nav a { ... }</code>."},
      {title:"Hover", body:"Make buttons darker when the mouse is over them.", answer:"<code>button:hover { background: #0a7; }</code>."},
    ],
    mistakes:["Using ids for styling everything.","Forgetting the semicolon between declarations.","Using inline styles, which are hard to maintain."],
    callout:{title:"Naming", body:"Name classes by purpose (.price, .warning) not appearance (.red-text)."},
    activity:"Create style.css for your Top 3 Places page: a background colour, a font, a style for h1 and a .card class with a border and padding.",
    activityAnswer:"Example: body { font-family: Arial, sans-serif; background: #f7f7f7; } h1 { color: #007749; } .card { border: 1px solid #ccc; padding: 16px; border-radius: 8px; }.",
    examTip:"Count specificity: ids beat classes, classes beat elements.",
    keyterms:[{w:"Selector",d:"Chooses which elements a rule styles"},{w:"Specificity",d:"How strongly a selector targets an element"},{w:"Cascade",d:"Rules for deciding which CSS applies"}],
    quiz:[
      {q:"Which selector targets class=\"card\"?",opts:["card","#card",".card","*card"],a:2,et:"Dot for class."},
      {q:"Most specific:",opts:["p","#intro",".text","div p"],a:1,et:"ids win."},
      {q:"Best way to add CSS to many pages:",opts:["Inline styles","External stylesheet","style tag on each page","JavaScript"],a:1,et:"One file, many pages."},
    ],
    conclusion:"Selectors choose elements, properties style them, and the cascade decides which rule wins."},

  1: {emoji:"📦", subtitle:"Enrichment · The box model",
    illusText:"content → padding → border → margin.",
    hook:{title:"Why is my box too wide?", body:"You set a box to 300px wide, add padding and a border — and suddenly it's 342px and breaks your layout. Every web developer hits this. The answer is the <strong>box model</strong>: every element is a box with layers."},
    intro:"Every element is a rectangular box with four layers: <strong>content</strong> (text or images), <strong>padding</strong> (space inside the border), <strong>border</strong>, and <strong>margin</strong> (space outside, between boxes). By default (<code>box-sizing: content-box</code>), width applies only to the content, so total width = width + left/right padding + left/right border. With <code>box-sizing: border-box</code>, padding and border are included in the width — most developers set <code>*, *::before, *::after { box-sizing: border-box; }</code>. Shorthand: <code>padding: 10px 20px</code> (top/bottom, left/right); <code>margin: 0 auto</code> centres a block with a set width. <strong>Display</strong>: block (full width, new line — div, p, h1), inline (flows in text — a, span; ignores width/height), inline-block. Vertical margins between blocks can <strong>collapse</strong> (the larger one wins).",
    concepts:[
      {t:"green", title:"🧅 Four layers", body:"Content, padding, border, margin."},
      {t:"teal", title:"📐 border-box", body:"Width includes padding and border."},
      {t:"gold", title:"↔️ Centre it", body:"margin: 0 auto on a block with a width."},
    ],
    examples:[
      {title:"Calculate", body:"width: 300px; padding: 20px; border: 1px solid (content-box).", answer:"300 + 40 + 2 = <strong>342px</strong> total width."},
      {title:"Fix", body:"Make that box exactly 300px wide.", answer:"Add <code>box-sizing: border-box;</code>."},
      {title:"Centre", body:"Centre a 600px wide container.", answer:"<code>.container { width: 600px; margin: 0 auto; }</code>."},
    ],
    mistakes:["Confusing padding (inside) and margin (outside).","Setting width on inline elements like span.","Forgetting margin collapse between paragraphs."],
    callout:{title:"See it", body:"In developer tools, select an element to see its box model diagram with exact numbers."},
    activity:"Make three .card boxes 250px wide with 16px padding, a 2px border and 12px margin. Calculate their total width with and without border-box.",
    activityAnswer:"content-box: 250 + 32 + 4 = 286px (plus 24px of margin = 310px of space). border-box: 250px (plus 24px margin = 274px).",
    examTip:"Draw the four layers when solving width questions.",
    keyterms:[{w:"Padding",d:"Space between content and border"},{w:"Margin",d:"Space outside the border"},{w:"box-sizing",d:"Controls whether width includes padding and border"}],
    quiz:[
      {q:"Space between content and border is:",opts:["Margin","Padding","Outline","Gap"],a:1,et:"Inside the box."},
      {q:"width 200px + padding 10px each side (content-box) =",opts:["200px","210px","220px","240px"],a:2,et:"200 + 20."},
      {q:"margin: 0 auto does what?",opts:["Removes margins","Centres a block horizontally","Adds padding","Hides overflow"],a:1,et:"Needs a width."},
    ],
    conclusion:"Every element is a box of content, padding, border and margin — and border-box makes widths predictable."},

  2: {emoji:"🖌️", subtitle:"Enrichment · Colours and typography",
    illusText:"hex · rgb · hsl · font-family · rem · line-height.",
    hook:{title:"Why the flag colours have codes", body:"The green of the South African flag isn't just “green” — designers use exact codes so it looks the same on every screen and print. CSS works the same way: precise <strong>colours</strong> and readable <strong>typography</strong> make a site feel professional."},
    intro:"<strong>Colour formats</strong>: named (<code>green</code>), hex (<code>#007749</code>), rgb (<code>rgb(0,119,73)</code>), rgba with transparency (<code>rgba(0,0,0,.5)</code>), hsl (<code>hsl(156 100% 23%)</code> — hue, saturation, lightness, great for making shades). Set text <code>color</code> and <code>background-color</code>; gradients with <code>linear-gradient()</code>. Store a palette in <strong>CSS variables</strong>: <code>:root { --brand: #007749; }</code> then <code>color: var(--brand);</code>. <strong>Typography</strong>: <code>font-family</code> with fallbacks (<code>'Inter', Arial, sans-serif</code>); Google Fonts for web fonts; <code>font-size</code> in <strong>rem</strong> (relative to the root size, respects user settings); <code>font-weight</code>; <code>line-height</code> around 1.5 for body text; keep lines about 60–75 characters wide; limit yourself to two fonts.",
    concepts:[
      {t:"green", title:"🎨 Colour codes", body:"hex, rgb, hsl — and variables for a palette."},
      {t:"teal", title:"🔤 Fonts", body:"A family with fallbacks; two fonts maximum."},
      {t:"gold", title:"📏 rem and line-height", body:"Scalable sizes and comfortable spacing."},
    ],
    examples:[
      {title:"Variable", body:"Use one brand colour across the site.", answer:"<code>:root { --brand: #007749; }</code> and <code>button { background: var(--brand); }</code>."},
      {title:"Units", body:"Root size is 16px. What is 1.5rem?", answer:"<strong>24px</strong>."},
      {title:"Transparency", body:"A black overlay at 60% opacity.", answer:"<code>background: rgba(0,0,0,.6);</code>"},
    ],
    mistakes:["Using too many fonts and colours.","Setting body text in px, which ignores users' font settings.","Low contrast colour combinations."],
    callout:{title:"60-30-10", body:"Use a main colour for 60% of the design, a secondary for 30% and an accent for 10%."},
    activity:"Create a palette of four colours as CSS variables inspired by a South African place, and use them on your page.",
    activityAnswer:"Example (Karoo sunset): --sand: #E8C07D; --rust: #B5523B; --sky: #2E5E8C; --ink: #1F2933. Check contrast between text and backgrounds.",
    examTip:"Convert rem to px by multiplying by the root font size (usually 16px).",
    keyterms:[{w:"Hex code",d:"Six-digit colour code like #007749"},{w:"rem",d:"Size relative to the root font size"},{w:"CSS variable",d:"A reusable custom property like --brand"}],
    quiz:[
      {q:"With a 16px root, 2rem =",opts:["16px","24px","32px","2px"],a:2,et:"2 × 16."},
      {q:"Which includes transparency?",opts:["#FFFFFF","rgb()","rgba()","hsl()"],a:2,et:"The a is alpha."},
      {q:"Comfortable body line-height:",opts:["0.8","1.0","1.5","4"],a:2,et:"Easier to read."},
    ],
    conclusion:"Precise colours, a variable-based palette and readable typography make sites look professional and stay consistent."},

  3: {emoji:"↔️", subtitle:"Enrichment · Flexbox layout",
    illusText:"display:flex · justify-content (main axis) · align-items (cross axis) · gap.",
    hook:{title:"Centring a div — the classic joke", body:"For years, centring something vertically in CSS was so hard it became a joke among developers. Then <strong>Flexbox</strong> arrived: three lines of CSS, and navigation bars, card rows and perfectly centred content became easy."},
    intro:"Flexbox lays out items in <strong>one direction</strong>. On the parent: <code>display: flex;</code>. <code>flex-direction</code>: row (default) or column. The <strong>main axis</strong> follows the direction; the <strong>cross axis</strong> is perpendicular. <code>justify-content</code> aligns on the main axis (flex-start, center, flex-end, space-between, space-around, space-evenly). <code>align-items</code> aligns on the cross axis (stretch, center, flex-start, flex-end). <code>gap</code> adds space between items. <code>flex-wrap: wrap</code> lets items move to the next line on small screens. On children: <code>flex: 1</code> makes items share space equally; <code>flex: 0 0 200px</code> fixes a width. Perfect centring: <code>display:flex; justify-content:center; align-items:center;</code>.",
    concepts:[
      {t:"green", title:"➡️ One direction", body:"Row or column."},
      {t:"teal", title:"🎯 Two axes", body:"justify-content = main; align-items = cross."},
      {t:"gold", title:"📱 Wrap", body:"flex-wrap lets rows break on small screens."},
    ],
    examples:[
      {title:"Nav bar", body:"Logo on the left, links on the right.", answer:"<code>nav { display:flex; justify-content:space-between; align-items:center; }</code>"},
      {title:"Centre", body:"Centre a login box in the screen.", answer:"<code>body { display:flex; justify-content:center; align-items:center; min-height:100vh; }</code>"},
      {title:"Equal columns", body:"Three cards share the row equally.", answer:"<code>.card { flex: 1; }</code> inside a flex container."},
    ],
    mistakes:["Putting display:flex on the children instead of the parent.","Mixing up justify-content and align-items when the direction is column.","Forgetting flex-wrap, so cards squash on phones."],
    callout:{title:"Practice", body:"Free games like Flexbox Froggy teach flexbox in 20 minutes."},
    activity:"Build a navigation bar with a logo and four links using flexbox, then a row of three cards that wraps on small screens.",
    activityAnswer:"nav { display:flex; justify-content:space-between; align-items:center; } .cards { display:flex; flex-wrap:wrap; gap:16px; } .card { flex: 1 1 250px; } — cards wrap when there's less than ~250px each.",
    examTip:"When direction is column, the axes swap: justify-content works vertically.",
    keyterms:[{w:"Main axis",d:"The direction flex items flow"},{w:"Cross axis",d:"Perpendicular to the main axis"},{w:"gap",d:"Space between flex or grid items"}],
    quiz:[
      {q:"Which goes on the parent?",opts:["flex:1","display:flex","order:2","flex-basis"],a:1,et:"The container."},
      {q:"Spread items with space between them:",opts:["justify-content: space-between","align-items: stretch","flex-wrap: wrap","gap: 0"],a:0,et:"Main axis."},
      {q:"Default flex-direction:",opts:["column","row","wrap","reverse"],a:1,et:"Left to right."},
    ],
    conclusion:"Flexbox arranges items along one axis — perfect for nav bars, card rows and centring anything."},

  4: {emoji:"🔲", subtitle:"Enrichment · CSS Grid",
    illusText:"grid-template-columns: repeat(3, 1fr) · gap · grid-template-areas.",
    hook:{title:"Design like a newspaper", body:"Newspapers and magazines have used grids for a century: columns, a big headline across the top, a sidebar. <strong>CSS Grid</strong> brings that power to the web — rows <em>and</em> columns at the same time."},
    intro:"Grid lays out in <strong>two dimensions</strong>. Parent: <code>display: grid;</code>. Define columns: <code>grid-template-columns: 200px 1fr 1fr;</code> — the <strong>fr</strong> unit means a fraction of the free space. <code>repeat(3, 1fr)</code> makes three equal columns. Responsive without media queries: <code>repeat(auto-fit, minmax(220px, 1fr))</code>. <code>gap</code> spaces cells. Place items: <code>grid-column: 1 / 3</code> (span from line 1 to line 3) or <code>grid-column: span 2</code>. Named areas: <code>grid-template-areas: \"header header\" \"sidebar main\" \"footer footer\";</code> then <code>header { grid-area: header; }</code>. Use <strong>Grid</strong> for whole-page and two-dimensional layouts and <strong>Flexbox</strong> for one-direction groups inside them.",
    concepts:[
      {t:"green", title:"🔳 Two dimensions", body:"Rows and columns together."},
      {t:"teal", title:"➗ fr unit", body:"Shares free space in proportions."},
      {t:"gold", title:"🗺️ Areas", body:"Name regions and place elements by name."},
    ],
    examples:[
      {title:"Three columns", body:"Equal columns with 20px gaps.", answer:"<code>display:grid; grid-template-columns: repeat(3, 1fr); gap: 20px;</code>"},
      {title:"Responsive cards", body:"Cards at least 220px wide that fill the row.", answer:"<code>grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));</code>"},
      {title:"fr maths", body:"Columns 1fr 2fr in 900px (no gap).", answer:"<strong>300px and 600px</strong>."},
    ],
    mistakes:["Using grid for a simple row of buttons (flexbox is simpler).","Forgetting that line numbers start at 1.","Mismatched names in grid-template-areas."],
    callout:{title:"Grid + Flexbox", body:"Grid for the page skeleton, Flexbox for the contents of each area."},
    activity:"Build a page layout with grid-template-areas: header across the top, sidebar and main in the middle, footer at the bottom.",
    activityAnswer:".page { display:grid; grid-template-columns: 220px 1fr; grid-template-areas: \"header header\" \"sidebar main\" \"footer footer\"; gap:16px; } header{grid-area:header;} aside{grid-area:sidebar;} main{grid-area:main;} footer{grid-area:footer;}",
    examTip:"Remember: 3 columns have 4 grid lines.",
    keyterms:[{w:"fr",d:"Fraction of the available space"},{w:"Grid line",d:"The lines between rows and columns"},{w:"grid-area",d:"Places an item in a named area"}],
    quiz:[
      {q:"Grid is best for:",opts:["One-direction rows","Two-dimensional layouts","Animations","Fonts"],a:1,et:"Rows and columns."},
      {q:"repeat(4, 1fr) creates:",opts:["4 rows","4 equal columns","1 column","4px gaps"],a:1,et:"Four fractions."},
      {q:"grid-column: 1 / 3 spans:",opts:["1 column","2 columns","3 columns","The whole grid"],a:1,et:"From line 1 to line 3."},
    ],
    conclusion:"CSS Grid builds two-dimensional layouts with fr units and named areas — pair it with Flexbox inside each area."},

  5: {emoji:"📱", subtitle:"Enrichment · Responsive design and media queries",
    illusText:"Mobile first: base styles for phones, @media (min-width) for bigger screens.",
    hook:{title:"Most South Africans browse on phones", body:"In South Africa, the majority of internet use happens on smartphones — often on prepaid data. A site that only works on a desktop shuts most users out. <strong>Responsive design</strong> makes one site adapt to every screen."},
    intro:"<strong>Responsive design</strong> adapts layouts to screen size. Start with the viewport meta tag. Use <strong>fluid</strong> units (%, fr, rem, vw) and flexible images: <code>img { max-width: 100%; height: auto; }</code>. <strong>Media queries</strong> apply CSS at certain sizes: <code>@media (min-width: 768px) { .cards { grid-template-columns: repeat(3, 1fr); } }</code>. <strong>Mobile first</strong>: write the phone layout as the default and add min-width queries for tablets (~768px) and desktops (~1024px). Touch targets should be at least about 44×44px. Save data: compress images, use <code>loading=\"lazy\"</code> on images below the fold, and avoid heavy videos. Test with the device toolbar in developer tools.",
    concepts:[
      {t:"green", title:"📱 Mobile first", body:"Phone styles first, then bigger screens."},
      {t:"teal", title:"🧩 Media queries", body:"@media (min-width: ...) changes the layout."},
      {t:"gold", title:"💾 Save data", body:"Small images and lazy loading."},
    ],
    examples:[
      {title:"Query", body:"Two columns from 768px wide.", answer:"<code>@media (min-width: 768px) { .grid { grid-template-columns: 1fr 1fr; } }</code>"},
      {title:"Images", body:"Stop images overflowing on phones.", answer:"<code>img { max-width: 100%; height: auto; }</code>"},
      {title:"Lazy", body:"Load gallery images only when they're about to be seen.", answer:"<code>&lt;img src=\"...\" alt=\"...\" loading=\"lazy\"&gt;</code>"},
    ],
    mistakes:["Fixed widths like width: 1200px.","Designing on a desktop and squashing it for phones later.","Tiny tap targets placed close together."],
    callout:{title:"Test on a real phone", body:"Open your page on a cheap phone on mobile data — that's what many of your users have."},
    activity:"Make your Top 3 Places page responsive: one column on phones, three columns from 900px wide. Test with the device toolbar.",
    activityAnswer:".places { display:grid; gap:16px; } @media (min-width: 900px) { .places { grid-template-columns: repeat(3, 1fr); } } plus img { max-width:100%; height:auto; }.",
    examTip:"Mobile first means min-width media queries; desktop first uses max-width.",
    keyterms:[{w:"Media query",d:"CSS that applies only under certain conditions"},{w:"Mobile first",d:"Designing for small screens first"},{w:"Breakpoint",d:"Width where the layout changes"}],
    quiz:[
      {q:"Mobile-first media queries usually use:",opts:["max-width","min-width","orientation only","print"],a:1,et:"Add styles as screens grow."},
      {q:"Which keeps images inside their container?",opts:["max-width:100%","width:2000px","float:left","display:none"],a:0,et:"Fluid images."},
      {q:"Minimum comfortable touch target:",opts:["10px","24px","About 44px","200px"],a:2,et:"Fingers need space."},
    ],
    conclusion:"Fluid layouts, flexible images and mobile-first media queries make one site work on every screen and data budget."},
};

// ─── Module 2: JavaScript ───────────────────────────────────────────────────
LESSON_DB.webprog.m2 = {
  0: {emoji:"📦", subtitle:"Enrichment · Variables and data types",
    illusText:"let · const · string · number · boolean · null · undefined.",
    hook:{title:"The airtime calculator", body:"An app that tells you how many data bundles you can buy needs to <em>remember</em> your balance, the price and the result. In JavaScript, things you remember go into <strong>variables</strong> — named boxes that hold values of different <strong>types</strong>."},
    intro:"Declare variables with <code>let</code> (can change) and <code>const</code> (can't be reassigned); avoid the old <code>var</code>. Names: camelCase (<code>dataBalance</code>), no spaces, can't start with a number. <strong>Data types</strong>: <strong>string</strong> (text in quotes: <code>\"Mzansi\"</code>), <strong>number</strong> (<code>29.99</code>), <strong>boolean</strong> (<code>true</code>/<code>false</code>), <strong>undefined</strong> (declared, no value), <strong>null</strong> (deliberately empty), plus objects and arrays (next lessons). Check a type with <code>typeof</code>. <strong>Operators</strong>: + − * / % (remainder); <code>+</code> also joins strings. Template literals use backticks and <code>${}</code> to insert values into text. Compare with <code>===</code> (equal value and type) rather than <code>==</code>. Print to the console with <code>console.log()</code>.",
    concepts:[
      {t:"green", title:"📦 let and const", body:"const by default; let when the value must change."},
      {t:"teal", title:"🔤 Types", body:"string, number, boolean, null, undefined."},
      {t:"gold", title:"⚖️ ===", body:"Strict equality checks value and type."},
    ],
    examples:[
      {title:"Type", body:"<code>typeof \"42\"</code>", answer:"<strong>\"string\"</strong> — the quotes make it text."},
      {title:"Join", body:"<code>\"R\" + 50</code>", answer:"<strong>\"R50\"</strong> — + joins a string and a number."},
      {title:"Compare", body:"<code>5 == \"5\"</code> vs <code>5 === \"5\"</code>", answer:"<strong>true</strong> vs <strong>false</strong> — === also checks the type."},
    ],
    mistakes:["Reassigning a const.","Adding numbers that are actually strings (\"2\" + \"3\" = \"23\").","Using == and getting surprising results."],
    callout:{title:"Convert", body:"Number(\"42\") turns text into a number; String(42) does the reverse."},
    activity:"Write a script that stores a data price (R29) and a balance (R100), then logs how many bundles you can buy and the change left.",
    activityAnswer:"const price = 29; const balance = 100; const bundles = Math.floor(balance / price); const change = balance % price; console.log(bundles, change); // 3 bundles, R13 change",
    examTip:"Know which values are strings: anything in quotes, and all values from form inputs.",
    keyterms:[{w:"Variable",d:"Named storage for a value"},{w:"Data type",d:"The kind of value (string, number, boolean…)"},{w:"Strict equality",d:"=== compares value and type"}],
    quiz:[
      {q:"Which keyword can't be reassigned?",opts:["let","var","const","new"],a:2,et:"Constant binding."},
      {q:"100 % 29 =",opts:["3","13","29","71"],a:1,et:"Remainder after 3 × 29 = 87."},
      {q:"typeof true is:",opts:["\"string\"","\"number\"","\"boolean\"","\"true\""],a:2,et:"true/false values."},
    ],
    conclusion:"Variables store values of different types; use const by default and === for comparisons."},

  1: {emoji:"⚙️", subtitle:"Enrichment · Functions and scope",
    illusText:"function name(input) { ...; return output; } — reusable, testable blocks.",
    hook:{title:"Write once, use everywhere", body:"The VAT on every product in an online shop is calculated the same way. Instead of writing the sum a thousand times, you write it once as a <strong>function</strong> and call it whenever you need it."},
    intro:"A <strong>function</strong> is a reusable block of code. Declaration: <code>function addVat(price) { return price * 1.15; }</code>. Call it: <code>addVat(100)</code> → 115. <strong>Parameters</strong> are the names in the definition; <strong>arguments</strong> are the values you pass. <code>return</code> sends a value back and ends the function. Arrow functions: <code>const addVat = (price) =&gt; price * 1.15;</code>. Default parameters: <code>function greet(name = \"learner\")</code>. <strong>Scope</strong>: variables declared inside a function (or a block with let/const) only exist there — <strong>local scope</strong>; variables declared outside are <strong>global</strong>. Keep functions small, named with a verb (calculateTotal), and doing one job.",
    concepts:[
      {t:"green", title:"🔁 Reuse", body:"Define once, call many times."},
      {t:"teal", title:"↩️ return", body:"Sends the result back to the caller."},
      {t:"gold", title:"🔒 Scope", body:"Variables inside a function stay inside."},
    ],
    examples:[
      {title:"Call", body:"<code>function area(w, h) { return w * h; }</code> — what is <code>area(4, 5)</code>?", answer:"<strong>20</strong>."},
      {title:"Arrow", body:"Write an arrow function that doubles a number.", answer:"<code>const double = n =&gt; n * 2;</code>"},
      {title:"Scope", body:"A variable declared with let inside a function — can you use it outside?", answer:"<strong>No</strong> — it's local to the function."},
    ],
    mistakes:["Forgetting return, so the function gives undefined.","Confusing parameters and arguments.","Relying on global variables everywhere."],
    callout:{title:"Pure functions", body:"A function that only uses its inputs and returns an output is easy to test."},
    activity:"Write a function that takes a mark out of a total and returns the percentage rounded to one decimal place, and the NSC level (1–7).",
    activityAnswer:"function result(mark, total) { const pct = Math.round(mark / total * 1000) / 10; const level = pct >= 80 ? 7 : pct >= 70 ? 6 : pct >= 60 ? 5 : pct >= 50 ? 4 : pct >= 40 ? 3 : pct >= 30 ? 2 : 1; return { pct, level }; }",
    examTip:"Trace a function call step by step: substitute the arguments for the parameters.",
    keyterms:[{w:"Parameter",d:"Input name in a function definition"},{w:"Argument",d:"Value passed when calling a function"},{w:"Scope",d:"Where a variable can be used"}],
    quiz:[
      {q:"What does return do?",opts:["Prints a value","Sends a value back and ends the function","Declares a variable","Loops"],a:1,et:"Output of the function."},
      {q:"addVat(200) with price * 1.15 gives:",opts:["215","230","200.15","2300"],a:1,et:"200 × 1.15."},
      {q:"A variable declared inside a function is:",opts:["Global","Local","Constant","Shared"],a:1,et:"Function scope."},
    ],
    conclusion:"Functions package logic into reusable, testable pieces, and scope keeps their variables tidy."},

  2: {emoji:"🗂️", subtitle:"Enrichment · Arrays and objects",
    illusText:"Arrays: ordered lists [ ]. Objects: named properties { key: value }.",
    hook:{title:"A learner's report card in code", body:"A report card has a list of subjects and, for each one, a mark and a level. In JavaScript that's an <strong>array</strong> of <strong>objects</strong> — the way almost every app stores data, from WhatsApp chats to bank transactions."},
    intro:"An <strong>array</strong> is an ordered list: <code>const subjects = [\"Maths\", \"Life Sciences\", \"History\"];</code>. Index from 0: <code>subjects[0]</code> is \"Maths\". <code>.length</code> gives the count; <code>push()</code> adds to the end; <code>pop()</code> removes the last. An <strong>object</strong> groups named properties: <code>const learner = { name: \"Ayanda\", grade: 11, province: \"KZN\" };</code> — read with <code>learner.name</code>. Arrays of objects store records. Useful array methods: <code>forEach</code> (do something to each), <code>map</code> (make a new array), <code>filter</code> (keep matching items), <code>find</code> (first match), <code>reduce</code> (combine into one value). Loops: <code>for (const s of subjects) { ... }</code>. JSON (JavaScript Object Notation) is the text format used to send these structures between servers and apps.",
    concepts:[
      {t:"green", title:"📋 Arrays", body:"Ordered lists, index starts at 0."},
      {t:"teal", title:"🗃️ Objects", body:"Named properties — key: value."},
      {t:"gold", title:"🛠️ Methods", body:"map, filter, find, reduce."},
    ],
    examples:[
      {title:"Index", body:"<code>[\"Mon\",\"Tue\",\"Wed\"][2]</code>", answer:"<strong>\"Wed\"</strong> — indexes start at 0."},
      {title:"Filter", body:"Keep marks of 50 and above from <code>[45, 72, 50, 38]</code>.", answer:"<code>marks.filter(m =&gt; m &gt;= 50)</code> → <strong>[72, 50]</strong>."},
      {title:"Average", body:"Average of <code>[60, 70, 80]</code>.", answer:"<code>marks.reduce((a, b) =&gt; a + b, 0) / marks.length</code> → <strong>70</strong>."},
    ],
    mistakes:["Starting counting at index 1.","Mixing up . and [] when property names have spaces.","Changing an array while looping over it."],
    callout:{title:"Arrays of objects", body:"[{ subject: \"Maths\", mark: 72 }, { subject: \"History\", mark: 65 }] — the shape of most app data."},
    activity:"Store five subjects with marks as an array of objects. Log the subject with the highest mark and the average mark.",
    activityAnswer:"const r = [{s:'Maths',m:72},{s:'Life Sci',m:81},{s:'History',m:65},{s:'English',m:70},{s:'Geography',m:77}]; const best = r.reduce((a,b) => b.m > a.m ? b : a); const avg = r.reduce((t,x) => t + x.m, 0) / r.length; // best Life Sci, avg 73",
    examTip:"When tracing array code, write out the array and its indexes in a table.",
    keyterms:[{w:"Array",d:"Ordered list of values"},{w:"Object",d:"Collection of named properties"},{w:"JSON",d:"Text format for sending data"}],
    quiz:[
      {q:"The first item of an array is at index:",opts:["1","0","-1","first"],a:1,et:"Zero-based."},
      {q:"Which method keeps only matching items?",opts:["map","filter","push","pop"],a:1,et:"Returns a new array."},
      {q:"learner.grade reads:",opts:["An array item","An object property","A function","A string length"],a:1,et:"Dot notation."},
    ],
    conclusion:"Arrays hold ordered lists, objects hold named data, and together — with map, filter and reduce — they model real information."},

  3: {emoji:"🧩", subtitle:"Enrichment · DOM manipulation",
    illusText:"document.querySelector → change textContent, classes and styles.",
    hook:{title:"How a page changes without reloading", body:"When you like a post and the heart turns red instantly, the page didn't reload — JavaScript changed it through the <strong>DOM</strong> (Document Object Model), a live tree of every element on the page."},
    intro:"The browser turns HTML into the <strong>DOM</strong>, a tree of objects JavaScript can read and change. <strong>Select</strong> elements: <code>document.querySelector(\".score\")</code> (first match, CSS selector) and <code>document.querySelectorAll(\"li\")</code> (all matches). <strong>Change content</strong>: <code>el.textContent = \"Done!\"</code> (safe — treats text as text). <code>innerHTML</code> parses HTML — never put user input into it without escaping, or attackers can inject scripts (XSS). <strong>Change style</strong>: add or remove CSS classes with <code>el.classList.add(\"active\")</code>, <code>remove</code> and <code>toggle</code> (better than setting styles directly). <strong>Create elements</strong>: <code>const li = document.createElement(\"li\"); li.textContent = \"New\"; list.append(li);</code>. Remove with <code>el.remove()</code>. Read and set attributes: <code>img.src</code>, <code>el.setAttribute(\"aria-hidden\",\"true\")</code>.",
    concepts:[
      {t:"green", title:"🌳 The DOM", body:"A live tree of page elements."},
      {t:"teal", title:"🎯 Select", body:"querySelector / querySelectorAll with CSS selectors."},
      {t:"gold", title:"🛡️ textContent", body:"Safe for user text; innerHTML can run injected code."},
    ],
    examples:[
      {title:"Change text", body:"Show the score in an element with id \"score\".", answer:"<code>document.querySelector(\"#score\").textContent = score;</code>"},
      {title:"Toggle", body:"Switch dark mode on and off.", answer:"<code>document.body.classList.toggle(\"dark\");</code>"},
      {title:"Security", body:"Why not <code>box.innerHTML = userComment</code>?", answer:"A comment containing a <code>&lt;script&gt;</code> or event attribute could run code — use <strong>textContent</strong>."},
    ],
    mistakes:["Selecting elements before the HTML has loaded.","Putting user input into innerHTML.","Using querySelector when you need all matches."],
    callout:{title:"Load order", body:"Put your script at the end of the body or use &lt;script defer&gt; so the DOM exists first."},
    activity:"Make a page with a list and an input. When you click “Add”, create a new list item from the input text (using textContent) and clear the input.",
    activityAnswer:"btn.onclick = () => { const li = document.createElement('li'); li.textContent = input.value; list.append(li); input.value = ''; }; — test it with text like &lt;b&gt;hi&lt;/b&gt;: it should appear as plain text.",
    examTip:"Know the safe choice: textContent for user text, innerHTML only for trusted HTML.",
    keyterms:[{w:"DOM",d:"Document Object Model — the page as a tree of objects"},{w:"querySelector",d:"Finds the first element matching a CSS selector"},{w:"XSS",d:"Cross-site scripting — injecting malicious scripts"}],
    quiz:[
      {q:"Which is safest for user text?",opts:["innerHTML","textContent","outerHTML","document.write"],a:1,et:"No HTML parsing."},
      {q:"querySelectorAll returns:",opts:["One element","All matching elements","A string","A number"],a:1,et:"A NodeList."},
      {q:"classList.toggle(\"open\"):",opts:["Always adds","Always removes","Adds if missing, removes if present","Deletes the element"],a:2,et:"Switches it."},
    ],
    conclusion:"The DOM lets JavaScript read and change the page — select, update text safely, toggle classes and create elements."},

  4: {emoji:"🖱️", subtitle:"Enrichment · Events and listeners",
    illusText:"addEventListener('click' | 'input' | 'submit' | 'keydown', handler).",
    hook:{title:"Apps that respond to you", body:"Tap a button, type in a search box, swipe a photo — every interaction is an <strong>event</strong>. JavaScript <strong>listens</strong> for events and runs code in response. It's what turns a static page into an app."},
    intro:"Attach a listener: <code>button.addEventListener(\"click\", handleClick);</code>. Common events: <code>click</code>, <code>input</code> (every change in a field), <code>change</code>, <code>submit</code> (forms), <code>keydown</code>, <code>mouseover</code>, <code>DOMContentLoaded</code>. The handler receives an <strong>event object</strong>: <code>e.target</code> is the element that triggered it; <code>e.key</code> is the key pressed. Forms: <code>form.addEventListener(\"submit\", e =&gt; { e.preventDefault(); ... });</code> stops the page reloading so you can handle the data in JavaScript. <strong>Event delegation</strong>: put one listener on a parent and check <code>e.target</code> — works for items added later. Remove with <code>removeEventListener</code>. Prefer addEventListener over inline <code>onclick=\"\"</code> attributes.",
    concepts:[
      {t:"green", title:"👂 Listen", body:"addEventListener(type, handler)."},
      {t:"teal", title:"🎯 e.target", body:"Which element triggered the event."},
      {t:"gold", title:"✋ preventDefault", body:"Stop the browser's default action (e.g. form reload)."},
    ],
    examples:[
      {title:"Live count", body:"Show the number of characters as someone types.", answer:"<code>box.addEventListener(\"input\", () =&gt; count.textContent = box.value.length);</code>"},
      {title:"Form", body:"Handle a form without reloading.", answer:"In the submit handler call <code>e.preventDefault()</code> first."},
      {title:"Keys", body:"Do something when Enter is pressed.", answer:"<code>if (e.key === \"Enter\") { ... }</code> inside a keydown handler."},
    ],
    mistakes:["Calling the function when attaching it: addEventListener(\"click\", go()) runs immediately.","Forgetting preventDefault on submit.","Adding listeners to every item instead of delegating."],
    callout:{title:"Pass, don't call", body:"Write addEventListener(\"click\", go) — no brackets after go."},
    activity:"Build a tip calculator: an input for the bill and buttons for 10%, 15% and 20% that show the tip and total when clicked.",
    activityAnswer:"Each button: btn.addEventListener('click', () => { const bill = Number(input.value); const tip = bill * Number(btn.dataset.pct) / 100; out.textContent = `Tip R${tip.toFixed(2)} · Total R${(bill + tip).toFixed(2)}`; }); — R200 at 15% gives tip R30.00, total R230.00.",
    examTip:"Know the difference between input (every keystroke) and change (when the field loses focus).",
    keyterms:[{w:"Event",d:"Something that happens on the page (click, input…)"},{w:"Listener",d:"Function that runs when an event happens"},{w:"Delegation",d:"One listener on a parent handles many children"}],
    quiz:[
      {q:"Which stops a form from reloading the page?",opts:["e.stop()","e.preventDefault()","return true","form.reload()"],a:1,et:"Default action blocked."},
      {q:"Event fired on every keystroke in a text field:",opts:["change","input","submit","load"],a:1,et:"Live updates."},
      {q:"e.target is:",opts:["The page","The element that triggered the event","The server","The function"],a:1,et:"Where it happened."},
    ],
    conclusion:"Events make pages interactive: listen, read the event object, and prevent default behaviour when you handle it yourself."},

  5: {emoji:"📡", subtitle:"Enrichment · Fetch API and JSON",
    illusText:"fetch(url) → await response.json() → show the data.",
    hook:{title:"Live data in your app", body:"Weather apps, load-shedding schedules and exchange-rate apps all get fresh data from a server through an <strong>API</strong>. In JavaScript you ask for it with <code>fetch()</code> and get back <strong>JSON</strong> — then show it on the page."},
    intro:"An <strong>API</strong> (application programming interface) is a way for programs to talk to each other. A <strong>REST API</strong> gives data at URLs (endpoints). <code>fetch(url)</code> sends an HTTP request and returns a <strong>Promise</strong> — a value that arrives later. With <strong>async/await</strong>: <code>async function load() { const res = await fetch(url); if (!res.ok) throw new Error(res.status); const data = await res.json(); }</code>. <strong>JSON</strong> looks like JavaScript objects but is text: keys in double quotes. Convert with <code>JSON.parse()</code> and <code>JSON.stringify()</code>. Handle errors with <code>try/catch</code> and show a friendly message (no internet, server down). Send data with <code>fetch(url, { method: \"POST\", headers: {\"Content-Type\":\"application/json\"}, body: JSON.stringify(obj) })</code>. Never put secret API keys in front-end code — anyone can read them.",
    concepts:[
      {t:"green", title:"🔌 API", body:"Programs requesting data from other programs."},
      {t:"teal", title:"⏳ async/await", body:"Wait for the response without freezing the page."},
      {t:"gold", title:"🔐 No secrets", body:"Front-end code is public — keep keys on a server."},
    ],
    examples:[
      {title:"JSON", body:"Is <code>{name: 'Lindiwe'}</code> valid JSON?", answer:"<strong>No</strong> — JSON needs double quotes: <code>{\"name\": \"Lindiwe\"}</code>."},
      {title:"Errors", body:"What should the app do if fetch fails because the learner is offline?", answer:"Catch the error and show a <strong>friendly message</strong> with a retry button."},
      {title:"Check", body:"Why check <code>res.ok</code>?", answer:"fetch doesn't fail on 404 or 500 — <strong>res.ok</strong> is false for those status codes."},
    ],
    mistakes:["Forgetting await, so you work with a Promise instead of data.","Not handling errors.","Putting API secrets in front-end JavaScript."],
    callout:{title:"Public APIs to practise with", body:"Many free APIs (weather, countries, quotes) need no key — perfect for practice."},
    activity:"Fetch country data from a free public API (search for “REST Countries API”) for South Africa and display its capital cities, population and currency.",
    activityAnswer:"Answers vary by API version. Expected values: capitals Pretoria (executive), Cape Town (legislative), Bloemfontein (judicial); population about 60+ million; currency South African rand (ZAR). Check that errors are caught and shown.",
    examTip:"Remember the two awaits: one for the response, one for res.json().",
    keyterms:[{w:"API",d:"Interface that lets programs exchange data"},{w:"Promise",d:"A value that will be available later"},{w:"JSON",d:"Text format for data with double-quoted keys"}],
    quiz:[
      {q:"fetch() returns:",opts:["A string","A Promise","An array","HTML only"],a:1,et:"Use await or .then()."},
      {q:"Valid JSON key:",opts:["name","'name'","\"name\"","`name`"],a:2,et:"Double quotes only."},
      {q:"Where should secret API keys live?",opts:["In the HTML","In front-end JS","On a server","In a comment"],a:2,et:"Never in the browser."},
    ],
    conclusion:"fetch and async/await bring live JSON data into your app — handle errors and keep secrets on the server."},
};

